sources = json.loads(Path("source.json").read_text())
assert len(sources) == 24
assert set(drafts) == {source["number"] for source in sources}
answer = []
for source in sources:
    proposed_xml, reason, review_notes = drafts[source["number"]]
    item = {key: source[key] for key in ("code_id", "source_id", "source_sha256", "number")}
    item.update(proposed_xml=proposed_xml, reason=reason, review_notes=review_notes, status="rewrite_draft")
    answer.append(item)
Path("answer.json").write_text(json.dumps(answer, ensure_ascii=False, indent=2) + "\n")
